    BillingAccount = apps.get_model("billing", "BillingAccount")
    legacy = getattr(settings, "STRIPE_PRICES", {}) or {}
    for slug, name, order, featured, limits, prices in TIERS:
        plan, _ = Plan.objects.get_or_create(
            slug=slug, defaults={"name": name, "sort_order": order, "is_featured": featured}
        )
        PlanLimits.objects.get_or_create(plan=plan, defaults={**limits, **FLAGS})
        for interval, cents in prices:
            ids = legacy.get(slug, {}) if interval == "monthly" else {}
            PlanPrice.objects.get_or_create(
                plan=plan,
                billing_interval=interval,
                defaults={
                    "price_cents": cents,
                    "stripe_price_id": ids.get("base", ""),
                    "stripe_meter_price_id": ids.get("meter", ""),
                },
            )
    dev, _ = Plan.objects.get_or_create(
        slug="dev",
        defaults={
            "name": "Local development",
            "sort_order": 99,
            "is_active": False,
            "is_custom": True,
            "partner_label": "Development",
        },
    )
    PlanLimits.objects.get_or_create(plan=dev, defaults=FLAGS)
    for account in BillingAccount.objects.exclude(plan__in=["free", ""]):
        if account.plan == "unmapped":
            account.price_unmapped = True
            account.save(update_fields=["price_unmapped"])
            continue
        interval = (
            account.billing_interval
            if account.billing_interval in {"monthly", "annual"}
            else "monthly"
        )
        price = PlanPrice.objects.filter(plan__slug=account.plan, billing_interval=interval).first()
        if price:
            account.plan_price = price
            account.save(update_fields=["plan_price"])


